-- InSave Hub Cloudflare D1 Compatible SQL Export
PRAGMA foreign_keys=OFF;
CREATE TABLE "accounts_profile" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "display_name" varchar(120) NOT NULL, "avatar_url" varchar(500) NOT NULL, "auth_provider" varchar(24) NOT NULL, "google_sub_id" varchar(128) NULL UNIQUE, "email_verified" bool NOT NULL, "email_verification_token" varchar(128) NOT NULL, "email_verified_at" datetime NULL, "security_alerts_enabled" bool NOT NULL, "last_login_ip_hash" varchar(64) NOT NULL, "created_at" datetime NOT NULL, "updated_at" datetime NOT NULL, "user_id" integer NOT NULL UNIQUE REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "advertisements_adsession" ("id" char(32) NOT NULL PRIMARY KEY, "session_key" varchar(64) NOT NULL, "ip_hash" varchar(64) NOT NULL, "nonce_token" varchar(128) NOT NULL UNIQUE, "required_duration_seconds" integer unsigned NOT NULL CHECK ("required_duration_seconds" >= 0), "started_at" datetime NOT NULL, "eligible_at" datetime NOT NULL, "completed_at" datetime NULL, "status" varchar(16) NOT NULL, "created_at" datetime NOT NULL, "pending_download_id" char(32) NULL REFERENCES "downloads_download" ("id") DEFERRABLE INITIALLY DEFERRED, "user_id" integer NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "advertisements_freeaccesssession" ("id" char(32) NOT NULL PRIMARY KEY, "session_key" varchar(64) NOT NULL, "ip_hash" varchar(64) NOT NULL, "started_at" datetime NOT NULL, "expires_at" datetime NOT NULL, "is_active" bool NOT NULL, "downloads_used_count" integer unsigned NOT NULL CHECK ("downloads_used_count" >= 0), "revoked_reason" varchar(160) NOT NULL, "created_at" datetime NOT NULL, "source_ad_session_id" char(32) NULL UNIQUE REFERENCES "advertisements_adsession" ("id") DEFERRABLE INITIALLY DEFERRED, "user_id" integer NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "auth_group" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(150) NOT NULL UNIQUE);
CREATE TABLE "auth_group_permissions" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "group_id" integer NOT NULL REFERENCES "auth_group" ("id") DEFERRABLE INITIALLY DEFERRED, "permission_id" integer NOT NULL REFERENCES "auth_permission" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "auth_permission" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "content_type_id" integer NOT NULL REFERENCES "django_content_type" ("id") DEFERRABLE INITIALLY DEFERRED, "codename" varchar(100) NOT NULL, "name" varchar(255) NOT NULL);
CREATE TABLE "auth_user" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "password" varchar(128) NOT NULL, "last_login" datetime NULL, "is_superuser" bool NOT NULL, "username" varchar(150) NOT NULL UNIQUE, "last_name" varchar(150) NOT NULL, "email" varchar(254) NOT NULL, "is_staff" bool NOT NULL, "is_active" bool NOT NULL, "date_joined" datetime NOT NULL, "first_name" varchar(150) NOT NULL);
CREATE TABLE "auth_user_groups" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "user_id" integer NOT NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, "group_id" integer NOT NULL REFERENCES "auth_group" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "auth_user_user_permissions" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "user_id" integer NOT NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, "permission_id" integer NOT NULL REFERENCES "auth_permission" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "core_auditlog" ("id" char(32) NOT NULL PRIMARY KEY, "event_type" varchar(64) NOT NULL, "severity" varchar(16) NOT NULL, "actor_ip_hash" varchar(64) NOT NULL, "resource_type" varchar(64) NOT NULL, "resource_id" varchar(128) NOT NULL, "description" text NOT NULL, "metadata" text NOT NULL CHECK ((JSON_VALID("metadata") OR "metadata" IS NULL)), "path" varchar(255) NOT NULL, "method" varchar(16) NOT NULL, "created_at" datetime NOT NULL, "user_id" integer NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "core_siteconfiguration" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "singleton_id" smallint unsigned NOT NULL UNIQUE CHECK ("singleton_id" >= 0), "site_name" varchar(80) NOT NULL, "tagline" varchar(160) NOT NULL, "maintenance_mode" bool NOT NULL, "ad_countdown_seconds" integer unsigned NOT NULL CHECK ("ad_countdown_seconds" >= 0), "free_access_hours" integer unsigned NOT NULL CHECK ("free_access_hours" >= 0), "free_downloads_before_ad" integer unsigned NOT NULL CHECK ("free_downloads_before_ad" >= 0), "enable_advertisements" bool NOT NULL, "enable_donations" bool NOT NULL, "enable_google_oauth" bool NOT NULL, "enable_guest_downloads" bool NOT NULL, "rate_limit_analyze_per_min" integer unsigned NOT NULL CHECK ("rate_limit_analyze_per_min" >= 0), "rate_limit_download_per_min" integer unsigned NOT NULL CHECK ("rate_limit_download_per_min" >= 0), "rate_limit_auth_per_min" integer unsigned NOT NULL CHECK ("rate_limit_auth_per_min" >= 0), "rate_limit_password_reset_per_hour" integer unsigned NOT NULL CHECK ("rate_limit_password_reset_per_hour" >= 0), "rate_limit_oauth_per_min" integer unsigned NOT NULL CHECK ("rate_limit_oauth_per_min" >= 0), "rate_limit_donation_per_min" integer unsigned NOT NULL CHECK ("rate_limit_donation_per_min" >= 0), "preset_donation_amounts" varchar(120) NOT NULL, "donation_currency" varchar(8) NOT NULL, "minimum_donation_amount" integer unsigned NOT NULL CHECK ("minimum_donation_amount" >= 0), "maximum_donation_amount" integer unsigned NOT NULL CHECK ("maximum_donation_amount" >= 0), "ad_sponsor_title" varchar(120) NOT NULL, "ad_sponsor_body" text NOT NULL, "ad_sponsor_cta_text" varchar(60) NOT NULL, "ad_sponsor_cta_url" varchar(200) NOT NULL, "updated_at" datetime NOT NULL, CONSTRAINT "site_config_singleton_constraint" CHECK ("singleton_id" = 1));
CREATE TABLE "django_admin_log" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "object_id" text NULL, "object_repr" varchar(200) NOT NULL, "action_flag" smallint unsigned NOT NULL CHECK ("action_flag" >= 0), "change_message" text NOT NULL, "content_type_id" integer NULL REFERENCES "django_content_type" ("id") DEFERRABLE INITIALLY DEFERRED, "user_id" integer NOT NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, "action_time" datetime NOT NULL);
CREATE TABLE "django_content_type" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "app_label" varchar(100) NOT NULL, "model" varchar(100) NOT NULL);
CREATE TABLE "django_migrations" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "app" varchar(255) NOT NULL, "name" varchar(255) NOT NULL, "applied" datetime NOT NULL);
CREATE TABLE "django_session" ("session_key" varchar(40) NOT NULL PRIMARY KEY, "session_data" text NOT NULL, "expire_date" datetime NOT NULL);
CREATE TABLE "donations_donation" ("id" char(32) NOT NULL PRIMARY KEY, "donor_name" varchar(120) NOT NULL, "donor_email" varchar(254) NOT NULL, "is_anonymous" bool NOT NULL, "amount" decimal NOT NULL, "currency" varchar(8) NOT NULL, "message" varchar(280) NOT NULL, "provider" varchar(24) NOT NULL, "provider_order_id" varchar(128) NOT NULL UNIQUE, "provider_payment_id" varchar(128) NOT NULL, "provider_signature" varchar(256) NOT NULL, "status" varchar(20) NOT NULL, "ip_hash" varchar(64) NOT NULL, "completed_at" datetime NULL, "created_at" datetime NOT NULL, "user_id" integer NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, CONSTRAINT "donation_positive_amount_constraint" CHECK ("amount" > '0'));
CREATE TABLE "downloads_download" ("id" char(32) NOT NULL PRIMARY KEY, "session_key" varchar(64) NOT NULL, "ip_hash" varchar(64) NOT NULL, "source_url" varchar(500) NOT NULL, "shortcode" varchar(64) NOT NULL, "content_type" varchar(24) NOT NULL, "media_format" varchar(80) NOT NULL, "resolution" varchar(40) NOT NULL, "file_size_bytes" bigint NOT NULL, "file_size_label" varchar(32) NOT NULL, "media_title" varchar(240) NOT NULL, "author_handle" varchar(80) NOT NULL, "preview_metadata" text NOT NULL CHECK ((JSON_VALID("preview_metadata") OR "preview_metadata" IS NULL)), "download_token" varchar(128) NOT NULL UNIQUE, "status" varchar(24) NOT NULL, "access_mode" varchar(24) NOT NULL, "completed_at" datetime NULL, "created_at" datetime NOT NULL, "user_id" integer NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, "tool_id" bigint NULL REFERENCES "downloads_tool" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "downloads_downloadattempt" ("id" char(32) NOT NULL PRIMARY KEY, "raw_url" varchar(500) NOT NULL, "normalized_url" varchar(500) NOT NULL, "ip_hash" varchar(64) NOT NULL, "status" varchar(32) NOT NULL, "reason" varchar(255) NOT NULL, "created_at" datetime NOT NULL, "download_id" char(32) NULL REFERENCES "downloads_download" ("id") DEFERRABLE INITIALLY DEFERRED, "user_id" integer NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, "tool_id" bigint NULL REFERENCES "downloads_tool" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "downloads_tool" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(120) NOT NULL UNIQUE, "slug" varchar(120) NOT NULL UNIQUE, "category" varchar(24) NOT NULL, "short_description" varchar(220) NOT NULL, "detailed_description" text NOT NULL, "supported_url_hint" varchar(160) NOT NULL, "output_formats" varchar(120) NOT NULL, "badge_code" varchar(16) NOT NULL, "is_active" bool NOT NULL, "is_featured" bool NOT NULL, "display_order" smallint unsigned NOT NULL CHECK ("display_order" >= 0), "total_uses" integer unsigned NOT NULL CHECK ("total_uses" >= 0), "created_at" datetime NOT NULL, "updated_at" datetime NOT NULL);
