INSERT INTO "downloads_tool" VALUES(1,'Instagram Reel Downloader','reel-downloader','reel','Extract public vertical Reels in original frame rate with synchronized audio tracks.','Designed for creators and social media archivists managing public short-form video. Inspects public Reel streams, verifies codec parameters, and packages MP4 containers without watermarks or re-compression artifacts.','https://www.instagram.com/reel/C8xYz123AbC/','MP4 (H.264 1080x1920) / AAC Stereo','MOD-01',1,1,1,0,'2026-09-28 16:58:59.750308','2026-09-28 16:58:59.750308');
INSERT INTO "downloads_tool" VALUES(2,'Instagram Video Downloader','video-downloader','video','Download long-form public video broadcasts and feed videos at native bitrate.','Supports public feed videos and archival IGTV links. Resolves highest available public progressive or segmented video streams with full frame-dimension telemetry.','https://www.instagram.com/tv/C7vBn987XyZ/','MP4 (1080p / 720p) / AAC','MOD-02',1,1,2,0,'2026-09-28 16:58:59.756335','2026-09-28 16:58:59.756335');
INSERT INTO "downloads_tool" VALUES(3,'Instagram Image Downloader','image-downloader','image','Retrieve full-resolution public photography assets with original color profile.','Inspects public single-image posts and extracts the highest-resolution public CDN rendition (up to 1080x1350 portrait or 1080x1080 square) in clean sRGB format.','https://www.instagram.com/p/C9pQr456LmN/','JPEG / SVG High-Precision Preview','MOD-03',1,1,3,0,'2026-09-28 16:58:59.762570','2026-09-28 16:58:59.762570');
INSERT INTO "downloads_tool" VALUES(4,'Public Post Downloader','public-post-downloader','post','Unified inspector for multi-slide carousels and mixed-media public publications.','Automatically detects whether a public /p/ permalink contains a single photograph, a video clip, or a multi-item carousel package, presenting structured format options.','https://www.instagram.com/p/C6kLm321OpQ/','MP4 / JPEG / Structured Manifest','MOD-04',1,1,4,0,'2026-09-28 16:58:59.768574','2026-09-28 16:58:59.768574');
INSERT INTO "downloads_tool" VALUES(5,'Profile Media Utility','profile-media-utility','profile','Inspect public profile identity headers, avatar dimensions, and public handle status.','Provides a clean verification summary for public creator and brand handles, including public avatar asset resolution and canonical permalink structure.','https://www.instagram.com/instagram/','Profile Avatar Package / JSON Summary','MOD-05',1,1,5,0,'2026-09-28 16:58:59.773985','2026-09-28 16:58:59.773985');
INSERT INTO "downloads_tool" VALUES(6,'Content Information Extractor','content-info-extractor','metadata','Generate structured technical metadata reports for public Instagram permalinks.','Extracts public shortcode identifiers, canonical URLs, aspect ratio geometry, and publication parameters into a clean JSON document for editorial workflows.','https://www.instagram.com/p/C5aBc789DeF/','JSON Technical Manifest','MOD-06',1,1,6,0,'2026-09-28 16:58:59.779982','2026-09-28 16:58:59.779982');
